        flash("No file selected")
        return redirect(url_for("lab1"))

    file = request.files["file"]
    if file.filename == "":
        flash("No file selected")
        return redirect(url_for("lab1"))

    if file and allowed_file(file.filename):
        try:
            # Intentionally vulnerable YAML loading
