def xxe_parse():
    """Parse XML input securely"""
    if request.method == "POST":
        try:
            from defusedxml import minidom as safe_minidom

            # Parse the XML data securely using defusedxml
            doc = safe_minidom.parseString(request.data.decode("utf-8"))

            # Extract text from the XML
            for node in doc.getElementsByTagName("text"):
                if node.firstChild:
                    text = node.firstChild.nodeValue
                    # Update the comment in database
                    comment = Comment.query.first()
                    if comment:
                        comment.comment = text
                    else:
                        comment = Comment(comment=text)
                        db.session.add(comment)
                    db.session.commit()
                    break

            return render_template("xxe_lab.html")
        except Exception as e:
            print(f"Error parsing XML: {str(e)}")
            return render_template("xxe_lab.html", error="Error processing XML data")

    return render_template("xxe_lab.html")
